/* Merge: list order first (hand-written data.js entries win), then any data.js extras. */
(function () {
  const existing = new Map(N3.KANJI.map(k => [k.k, k]));
  const more = new Map(N3.KANJI_MORE.map(r => [r[0], r]));
  const fromRow = r => ({
    id: 'k-' + r[0].codePointAt(0).toString(16),
    k: r[0], on: r[1], kun: r[2], mean: r[3],
    words: [r[4], r[5]], ex: r[6], en: r[7]
  });
  const ordered = [];
  for (const ch of N3.N3_ORDER) {
    if (existing.has(ch)) ordered.push(existing.get(ch));
    else if (more.has(ch)) ordered.push(fromRow(more.get(ch)));
  }
  const listed = new Set(N3.N3_ORDER);
  N3.KANJI.forEach(k => { if (!listed.has(k.k)) ordered.push(k); });
  N3.KANJI = ordered;
})();
